window.addEventListener("scroll",()=>{const t=window.scrollY,n=document.documentElement.scrollHeight-window.innerHeight,l=n>0?t/n*100:0;document.getElementById("progress-bar").style.width=l+"%";const o=document.getElementById("back-to-top");o&&o.classList.toggle("opacity-0 pointer-events-none",t<300)});localStorage.getItem("cookieAccepted")?document.getElementById("cookie-banner").classList.add("translate-y-full"):setTimeout(()=>document.getElementById("cookie-banner").classList.remove("translate-y-full"),1e3);document.getElementById("cookie-accept").addEventListener("click",()=>{localStorage.setItem("cookieAccepted","true"),document.getElementById("cookie-banner").classList.add("translate-y-full")});const c=document.getElementById("mobile-menu-btn"),e=document.getElementById("mobile-menu"),s=document.getElementById("mobile-menu-close");c?.addEventListener("click",()=>e?.classList.remove("translate-x-full"));s?.addEventListener("click",()=>e?.classList.add("translate-x-full"));window.closeMobileMenu=()=>e?.classList.add("translate-x-full");
